def backfill_workspace_policies(apps, schema_editor):
    """Enumerate existing deployment/content/identity scopes; never invent approvals."""
    Policy = apps.get_model("sitecontent", "WorkspacePolicy")
    database = schema_editor.connection.alias
    sites = set()
    # Configuration alone is not evidence of an existing tenant: fresh installs
    # must retain conservative defaults. Only durable prior rows justify compatibility.
    for model in apps.get_app_config("sitecontent").get_models():
        if model is Policy or not any(field.name == "site_id" for field in model._meta.fields):
            continue
        sites.update(model.objects.using(database).order_by().values_list("site_id", flat=True).distinct())
    organizations = {}
    if schema_editor.connection.vendor == "postgresql":
        with schema_editor.connection.cursor() as cursor:
            cursor.execute("SELECT to_regclass('public.api_identity_organizations')")
            if cursor.fetchone()[0] is not None:
                cursor.execute("SELECT tenant_id, id FROM public.api_identity_organizations")
                organizations = dict(cursor.fetchall())
                sites.update(organizations)
    for site in sorted(sites):
        if not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,62}", site):
            raise RuntimeError("workspace_policy_backfill_invalid_scope")
        Policy.objects.using(database).get_or_create(
            site_id=site,
            defaults={"organization_id": organizations.get(site), "schema_version": 1,
                      "version": 1, "require_review": False,
                      "public_access": "public_allowed", "provenance": "migrated"},
        )


